 item.dataset.open='false';if(latest)item.dataset.latest='true';head.setAttribute('aria-expanded','false');head.setAttribute('aria-controls',id);panel.id=id;panel.setAttribute('role','region');panel.setAttribute('aria-label','Cambios de la versión '+release.version);panel.inert=true;
