// Comprobación de versión compartida: se ejecuta sola una vez por sesión autenticada y a petición; nunca instala nada.
const systemCheck={state:'idle',info:null,error:'',lastSuccess:'',running:null};
function runSystemCheck(force=false,announce=true){
 const key='ordenes-pro:comprobacion:'+String(csrf).slice(0,16);
 if(!force){try{const saved=JSON.parse(sessionStorage.getItem(key)||'null');if(saved){Object.assign(systemCheck,{state:'done',info:saved.info,lastSuccess:saved.at,error:''});document.dispatchEvent(new CustomEvent('systemcheck'));return Promise.resolve(saved.info);}}catch{}}
 if(systemCheck.running)return systemCheck.running;
 const emit=()=>document.dispatchEvent(new CustomEvent('systemcheck')),frame=()=>new Promise(resolve=>setTimeout(resolve,matchMedia('(prefers-reduced-motion: reduce)').matches?0:260));
 systemCheck.state='working';systemCheck.step=0;emit();if(force&&announce)toast('Consultando la versión publicada','info',undefined,{title:'Comprobando actualizaciones…',release:'checking',id:'system-check',duration:0});
 systemCheck.running=api('/api/system/check',{}).then(async info=>{systemCheck.step=1;emit();await frame();systemCheck.step=2;emit();await frame();Object.assign(systemCheck,{state:'done',info,error:'',lastSuccess:info.checked_at});try{sessionStorage.setItem(key,JSON.stringify({info,at:info.checked_at}));}catch{}
   if(info.update_available){let told='';try{told=sessionStorage.getItem(key+':aviso')||'';}catch{}if(told!==info.latest.version||force){dismissToast('system-check');toast('Release '+info.latest.version+' listo para cargar','info',autoUpdate.server?{label:'Actualizar ahora',run:()=>autoApply(true)}:{label:'Ver novedades',run:()=>go('system')},{title:'Nueva actualización disponible',duration:10000,release:'new',secondary:{label:'Posponer',run:()=>{if(autoUpdate.server)autoPostpone();}}});try{sessionStorage.setItem(key+':aviso',info.latest.version);}catch{}}}else if(force&&announce){dismissToast('system-check');toast('Versión '+(info.installed?info.installed.version:document.body.dataset.version)+' activa','success',undefined,{title:'Sistema actualizado',release:'done',duration:5000});}dismissToast('system-check');return info;})
  .catch(error=>{Object.assign(systemCheck,{state:'error',error:error.message});dismissToast('system-check');if(force&&announce)toast(error.message||'Sin respuesta del servidor','error',{label:'Reintentar',run:()=>runSystemCheck(true)},{title:'No se pudo comprobar la versión',release:'error',duration:9000});return null;})
  .finally(()=>{systemCheck.running=null;document.dispatchEvent(new CustomEvent('systemcheck'));});
 return systemCheck.running;
}
// Etiqueta «Release» del encabezado: refleja la comprobación real de versiones y abre un panel compacto con el detalle.
// Auto Update Safe: detecta que el servidor ya ejecuta una versión posterior a la cargada en esta pestaña y la recarga a los cinco minutos, solo si no hay trabajo sin guardar.
const autoUpdate={loaded:'',server:'',info:null,state:'ok',deadline:0,ticker:null,checking:false,failures:0,reload:()=>location.reload(),listeners:new Set()};
const autoKey=version=>'ordenes-pro:actualizacion:'+version;
function autoRemaining(){const seconds=Math.max(0,Math.ceil((autoUpdate.deadline-Date.now())/1000));return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');}
function autoEmit(){for(const listener of autoUpdate.listeners)listener();}
// Trabajo pendiente real: ventanas abiertas, guardados en curso, fotos en proceso, configuración modificada o texto escrito en los editores.
function updateBlockers(){
 const found=[];if(document.querySelector('dialog[open]'))found.push('una ventana abierta');if(document.querySelector('form[data-saving=true],[data-busy=true]'))found.push('un guardado en curso');if(typeof orderPhotoBusy!=='undefined'&&orderPhotoBusy>0)found.push('fotos en proceso');
 if([...document.querySelectorAll('.config-dirty')].some(node=>node.textContent.trim()))found.push('cambios de configuración sin guardar');
 if([...document.querySelectorAll('.ai-ask textarea,#adi-input,.mail-link input,.mail-editor')].some(node=>((node.value??node.textContent)||'').trim()))found.push('texto sin enviar');
 return found;
}
function autoSetDeadline(time){autoUpdate.deadline=time;try{localStorage.setItem(autoKey(autoUpdate.server),String(time));}catch{}}
function autoApply(force=false){
 const blockers=updateBlockers();if(blockers.length){autoUpdate.state='waiting';autoEmit();if(force)toast('Guarda o cierra primero: '+blockers.join(', ')+'.','warning',undefined,{title:'Actualización lista'});return false;}
 autoUpdate.state='updating';autoEmit();toast('Cargando Release '+autoUpdate.server,'info',undefined,{title:'Actualizando interfaz…',release:'updating',id:'auto-updating',duration:0});try{sessionStorage.setItem('ordenes-pro:actualizando',autoUpdate.server);}catch{}clearInterval(autoUpdate.ticker);setTimeout(()=>autoUpdate.reload(),450);return true;
}
