function adoptMailPrefs(){if(!currentUser?.mail_prefs)return;try{const local=JSON.parse(localStorage.getItem(mailPrefsKey())||'{}');localStorage.setItem(mailPrefsKey(),JSON.stringify({...local,...currentUser.mail_prefs,custom:!!local.custom}));}catch{}}
