  const notes={received:[[659.25,0,.2],[830.61,.14,.2],[987.77,.28,.22],[1318.5,.44,.5]],sent:[[587.33,0,.12],[880,.1,.22]],error:[[233.08,0,.22],[174.61,.2,.32]]}[type];if(!notes)return false;
  for(const[frequency,at,length]of notes)for(const[kind,level]of [['sine',.2],['triangle',.07]]){const osc=mailAudio.createOscillator(),gain=mailAudio.createGain();osc.type=kind;osc.frequency.value=frequency;gain.gain.setValueAtTime(.0001,now+at);gain.gain.linearRampToValueAtTime(level*volume,now+at+.012);gain.gain.exponentialRampToValueAtTime(.0001,now+at+length);osc.connect(gain);gain.connect(mailAudio.destination);osc.start(now+at);osc.stop(now+at+length+.04);}
