 function fit(){if(!node.isConnected){stop.abort();return;}const height=view?.height||innerHeight;let scroller=node.parentElement;while(scroller&&scroller!==document.body&&!/(auto|scroll)/.test(getComputedStyle(scroller).overflowY))scroller=scroller.parentElement;let space,offset;if(!scroller||scroller===document.body){space=height;offset=node.getBoundingClientRect().top+scrollY;}else{const box=scroller.getBoundingClientRect();space=Math.min(height,box.bottom)-Math.max(0,box.top);offset=node.getBoundingClientRect().top-box.top+scroller.scrollTop;}node.style.setProperty(property,Math.floor(Math.max(Math.min(minimum,space-12),space-offset-14))+'px');}
