function normalizeGeo(value){return value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es').trim();}
function populateGeo(level){const list=$('geo-'+level);list.replaceChildren();for(const row of geoState[level]){const option=el('option');option.value=level==='localities'?row.name:row.name+' · '+row.code;option.label=row.kind?row.kind:'';list.append(option);}}
