async function acceptGeo(index){const name=geoFields[index],input=$('order-'+name),code=$('order-'+name+'_code'),level=geoLevels[index];const matches=geoState[level].filter(row=>normalizeGeo(input.value)===normalizeGeo(row.name+' · '+row.code)||normalizeGeo(input.value)===normalizeGeo(row.name));const row=matches.length===1?matches[0]:null;const next=row?.code||'';if(next===code.value)return;code.value=next;clearGeoBelow(index);if(row){input.value=row.name+' · '+row.code;input.removeAttribute('aria-invalid');$('error-'+name).textContent='';await fetchGeo(index<2?geoLevels[index+1]:'localities');}}
function hasReceptionInput(){return !!$('order-client_id').value||orderPhotos.length>0||[...$('order-form').querySelectorAll('input,textarea,select')].some(field=>field.name&&field.type!=='hidden'&&!['priority','assigned_to'].includes(field.name)&&(['checkbox','radio'].includes(field.type)?field.checked!==field.defaultChecked:field.tagName==='SELECT'?field.selectedIndex!==Math.max(0,[...field.options].findIndex(option=>option.defaultSelected)):field.value.trim()));}
