 if(data.stale)box.append(el('p','Dato desactualizado: no hay conexión con el proveedor. Se muestra la última lectura válida.','popover-warning'));
 const list=el('dl',undefined,'popover-facts'),fact=(label,value)=>{const row=el('div');row.append(el('dt',label),el('dd',value));list.append(row);};
 if(Number.isFinite(data.feels_like))fact('Sensación térmica (estimada)',data.feels_like+' °C');if(Number.isFinite(data.humidity))fact('Humedad',data.humidity+' %');if(Number.isFinite(data.wind_kmh))fact('Viento',data.wind_kmh+' km/h');if(Number.isFinite(data.precipitation_mm))fact('Lluvia prevista (próxima hora)',String(data.precipitation_mm).replace('.',',')+' mm');if(data.valid_at)fact('Pronóstico para',hour(data.valid_at));if(data.updated_at)fact('Actualizado por el proveedor',hour(data.updated_at));if(data.checked_at)fact('Última consulta correcta',hour(data.checked_at));box.append(list);
