let weatherRequest=null,weatherNextAttempt=0;
// Aviso discreto cuando el proveedor publica un cambio real: otra condición o una variación de 4 °C o más. Como mucho uno cada 30 minutos.
let weatherNoted=null,weatherNotedAt=0;
function noteWeatherChange(data){if(!data.available||data.stale)return;const now=Date.now();if(!weatherNoted){weatherNoted={label:data.label,temperature:data.temperature};return;}const place=weatherCity(data).split(',')[0],delta=data.temperature-weatherNoted.temperature,changed=data.label!==weatherNoted.label,big=Math.abs(delta)>=4;if(!changed&&!big)return;if(now-weatherNotedAt>=1800000&&typeof toast==='function'){toast(changed?'El clima cambió a '+data.label.toLowerCase()+' en '+place+' ('+data.temperature+' °C).':'La temperatura prevista en '+place+' '+(delta<0?'descendió':'subió')+' a '+data.temperature+' °C.','info',null,{title:'Clima'});weatherNotedAt=now;}weatherNoted={label:data.label,temperature:data.temperature};}
