  if(innerWidth<=860)$('header-search-slot').append(search);else tools.insertBefore(search,tools.querySelector('#header-status')||tools.querySelector('.user-area'));
  if(innerWidth<1000)$('header-status-slot').append(status);else tools.insertBefore(status,tools.querySelector('.user-area'));
