 d.append(el('p','Días naturales contados desde la fecha de ingreso. Se aplica al cálculo de todas las órdenes; no modifica ningún registro.','stay-intro'));
 const inputs={};for(const[name,label]of[['notice','Recordatorio preventivo desde el día'],['near','Próximo al vencimiento desde el día'],['limit','Plazo administrativo (días)']]){inputs[name]=field(form,label,name,String(current[name]??''),{type:'number',required:true});inputs[name].min='1';inputs[name].max='730';inputs[name].inputMode='numeric';}
