  log.hidden=!info.history.length;logTitle.textContent='Historial de envíos ('+info.history.length+')';list.replaceChildren();for(const item of info.history){const li=el('li');li.append(el('strong',labels[item.result]+(item.recipient?' · '+item.recipient:'')),el('small',formatOrderDate(item.created_at)+' · '+(item.mode==='auto'?'Automático':'Reenvío manual')+(item.actor?' · '+item.actor:'')+(item.result==='failed'&&item.detail?' · '+item.detail:'')));list.append(li);}
