   const basic=[['Fila',row=>String(row.row)],['Cliente',row=>row.name||'(sin nombre)'],['Identificación',row=>row.identification||'—'],['Teléfono',row=>row.phone||'—'],['Correo',row=>row.email||'—'],['Ciudad',row=>row.city||'—']];
   if(c.new)out.append(section('Clientes nuevos (primeros '+preview.new.length+')',c.new,tableOf(preview.new,[...basic,['Avisos',row=>row.warnings.join(' ')||'Ficha completa']]),true));
   if(preview.duplicates.length)out.append(section('Duplicados: revisa cada uno',c.duplicate,tableOf(preview.duplicates,[['Fila',row=>String(row.row)],['En el archivo',row=>[row.name,row.identification,row.phone,row.email].filter(Boolean).join(' · ')],['Ficha existente',row=>[row.existing.name,row.existing.identification,row.existing.phone,row.existing.email].filter(Boolean).join(' · ')],['Decisión',row=>{const pick=el('select');pick.dataset.mergeRow=row.row;pick.setAttribute('aria-label','Decisión para la fila '+row.row);pick.add(new Option('Omitir (no cambiar la ficha)',''));pick.add(new Option('Completar solo campos vacíos','fill'));return pick;}]]),true));
   if(preview.repeated.length)out.append(section('Repetidos dentro del archivo',c.repeated,tableOf(preview.repeated,[...basic.slice(0,3),['Motivo',row=>row.detail]])));
   if(preview.skipped.length)out.append(section('Omitidos',c.skipped,tableOf(preview.skipped,[...basic.slice(0,3),['Motivo',row=>row.detail]])));
