async function refresh(){
 const data=await api('/api/dashboard');const states=$('operations-states');states.replaceChildren();
 for(const[code,icon]of [['pendiente','waiting'],['reparacion','work'],['esperando_cliente','message'],['presupuesto','quote'],['listo','ready'],['entregado','delivered']]){
 const item=button('',()=>go('orders',new URLSearchParams({status:code})),'operation-indicator status-'+code);item.setAttribute('aria-label',statusNames[code]+': '+String(data.counts[code]||0)+'. Ver órdenes');const chip=el('span',undefined,'indicator-icon');chip.append(operationIcon(icon));item.append(chip,el('strong',String(data.counts[code]||0)),el('span',statusNames[code],'indicator-label'));states.append(item);}
 renderAttention(data.attention,data.today);renderTracking(data.activity);renderMaintenanceRows($('operations-maintenance'),data.maintenance,data.today,true);
 renderHomeDeliveries(data.deliveries);renderHomeAppointments(data.appointments||[],data.today);renderHomeAssistance(data.assistance);
 // La carga inicial solo trae las citas de hoy; la agenda completa añade la próxima cita y deja el panel al día.
 if(['administrador','tecnico'].includes(currentUser.role))refreshHomeAppointments();
}
function operationEmpty(root,icon,text,action){const box=el('div',undefined,'operation-empty');box.append(operationIcon(icon),el('p',text));if(action)box.append(action);root.append(box);}
function dashboardDate(value){if(!value)return 'Sin fecha prevista';return new Intl.DateTimeFormat('es-EC',{day:'2-digit',month:'short',year:'numeric',timeZone:'America/Guayaquil'}).format(new Date(value+'T12:00:00-05:00'));}
function renderHomeDeliveries(rows){const root=$('operations-deliveries');root.replaceChildren();if(!rows.length){operationEmpty(root,'delivery','No hay entregas próximas programadas.');return;}
 for(const row of rows){const item=el('article',undefined,'home-record'),info=el('div');info.append(el('strong',row.client),el('p',[row.brand,row.model].filter(Boolean).join(' ')||'Equipo sin especificar'),el('small',row.code+' · '+dashboardDate(row.estimated_delivery)));const action=el('div',undefined,'home-record-actions');action.append(orderBadge(row.status_code,row.status,row.id),button('Ver orden',()=>go('orders',new URLSearchParams({id:row.id})),'text-action'));item.append(info,action);root.append(item);}}
// Citas de Hoy: solo las citas activas de la fecha actual (hora de Ecuador), en filas compactas que abren su detalle real.
// Se sincroniza por consulta periódica cada 30 s (no hay conexión persistente): una cita nueva tarda como máximo ese tiempo en aparecer.
const homeAppointmentsSeen=new Set();let homeAppointmentsFirst=true,homeAppointmentsTimer=null;
// Colores de estado del panel Citas de Hoy (borde lateral, icono y distintivo; nunca el fondo completo).
