 const sync=$('home-appointments-sync'),stamp=()=>{if(sync){sync.dataset.state='ok';sync.textContent='Actualizado · '+new Intl.DateTimeFormat('es-EC',{timeZone:'America/Guayaquil',hour:'2-digit',minute:'2-digit'}).format(new Date(Date.now()+clockOffset));}};
 const sig=JSON.stringify([list.map(row=>[row.id,row.status,row.starts_at,row.customer_name,row.service_label,row.brand,row.model,homeLive.fresh.has(row.id)]),upcoming&&!list.length?[upcoming.id,upcoming.starts_at,upcoming.customer_name]:0]);
