  if(cancelled){badge.classList.add('live-cancelled-badge');badge.prepend(systemIcon(agendaActionIcons.cancel));item.classList.add('live-cancelled');}
  tags.append(badge);item.title=cancelled?'Cita cancelada · '+row.public_code:'Abrir la cita '+row.public_code;item.setAttribute('aria-label','Cita de las '+row.starts_at.slice(11,16)+', '+row.customer_name+', '+row.service_label+', '+(agendaStatus[row.status]||[row.status])[0]+(isNew?', nueva':''));
