 const items=[['Conversaciones nuevas','new_conversations','#5BC5E8'],['Clientes esperando respuesta','waiting','#EABC6C'],['Transferidas por ADI','transferred','#A99AF2']],total=items.reduce((sum,[,key])=>sum+(Number(data?.[key])||0),0),waiting=Number(data?.waiting)||0,dot=$('home-live-dot'),open=button('Abrir panel de atención',()=>go('live'),'primary assistance-open');open.prepend(systemIcon('M3 11h3a2 2 0 0 1 2 2v3a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2zm0 0a9 9 0 1 1 18 0m0 0v5a2 2 0 0 1-2 2h-1a2 2 0 0 1-2-2v-3a2 2 0 0 1 2-2z'));
