 if(!total){const empty=el('div',undefined,'assistance-empty'),icon=el('span',undefined,'assistance-empty-icon'),text=el('div');icon.append(systemIcon('M21.801 10A10 10 0 1 1 17 3.335 M9 11l3 3L22 4'));text.append(el('strong','Sin atenciones pendientes'),el('small','Todos los clientes han sido atendidos o no hay conversaciones activas en espera.'));empty.append(icon,text);root.append(empty,open);for(const[,key]of items)assistanceCounts[key]=0;return;}
