function ecuadorPhone(phone){return whatsappNumber(phone).number;}
// Número para wa.me: solo dígitos, con código de país y sin duplicarlo. No comprueba si el número tiene cuenta de WhatsApp (eso solo lo sabe WhatsApp).
function whatsappNumber(phone){const raw=String(phone||'').trim(),international=/^\s*(\+|00)/.test(raw);let p=raw.replace(/\D/g,'');if(!p)return{ok:false,number:'',reason:'El cliente no tiene un teléfono registrado.'};
 if(p.startsWith('00'))p=p.slice(2);if(p.startsWith('5930'))p='593'+p.slice(4);if(p.length===10&&p.startsWith('0'))p='593'+p.slice(1);else if(p.length===9&&p.startsWith('9'))p='593'+p;else if(p.length===9&&/^0[2-7]/.test(p))p='593'+p.slice(1);
 if(p.startsWith('593')){if(/^5939\d{8}$/.test(p))return{ok:true,number:p,reason:''};if(/^593[2-7]\d{7}$/.test(p))return{ok:false,number:p,reason:'El teléfono registrado parece un número fijo; WhatsApp necesita un celular.'};return{ok:false,number:p,reason:'El teléfono registrado está incompleto o tiene dígitos de más.'};}
 if(international&&p.length>=8&&p.length<=15)return{ok:true,number:p,reason:''};return{ok:false,number:p,reason:'El teléfono registrado no tiene un formato válido para WhatsApp.'};}
let whatsappOpenedAt=0;
// Abre la conversación con el mensaje preparado; el mensaje solo se envía cuando la persona pulsa Enviar en WhatsApp.
function openWhatsApp(phone,message){const target=whatsappNumber(phone);if(!target.ok){toast(target.reason+' Corrígelo en la ficha del cliente.','warning',undefined,{title:'WhatsApp'});return false;}if(Date.now()-whatsappOpenedAt<1500)return false;whatsappOpenedAt=Date.now();window.open('https://wa.me/'+target.number+(message?'?text='+encodeURIComponent(message):''),'_blank','noopener,noreferrer');toast('Se abrió WhatsApp con el mensaje preparado para '+'+'+target.number+'. Revisa y pulsa Enviar allí; Órdenes Pro no puede confirmar el envío.','info',undefined,{title:'WhatsApp'});return true;}
function whatsappLink(anchor,phone,message){const target=whatsappNumber(phone);anchor.href=target.ok?'https://wa.me/'+target.number+'?text='+encodeURIComponent(message):'#';anchor.target='_blank';anchor.rel='noopener noreferrer';if(!target.ok)anchor.title=target.reason;anchor.addEventListener('click',event=>{event.preventDefault();openWhatsApp(phone,message);});}
// Mensajes de WhatsApp de una orden: se rellenan con los datos reales y se pueden editar antes de abrir la conversación.
const whatsappTemplates=[['Recepción del equipo',o=>'Hola '+o.client+', le saludamos de PC-DOCTOR S.A. Recibimos su '+o.device+' con la orden '+o.code+'.'+o.track],['Diagnóstico técnico',o=>'Hola '+o.client+', ya tenemos el diagnóstico de su '+o.device+' (orden '+o.code+'): '+(o.findings||'[escriba aquí el diagnóstico]')+'.'],['Presupuesto',o=>'Hola '+o.client+', el presupuesto para su '+o.device+' (orden '+o.code+') es de '+(o.total||'[valor]')+'. Quedamos atentos a su aprobación.'],['Autorización de reparación',o=>'Hola '+o.client+', necesitamos su autorización para continuar con la reparación de su '+o.device+' (orden '+o.code+'). ¿Nos confirma por este medio?'],['Equipo listo para retirar',o=>'Hola '+o.client+', su '+o.device+' (orden '+o.code+') está listo para retirar en PC-DOCTOR S.A. Por favor presente su comprobante.'],['Recordatorio de pago',o=>'Hola '+o.client+', le recordamos el valor pendiente de la orden '+o.code+(o.total?': '+o.total:'')+'. Gracias por su atención.'],['Seguimiento de la orden',o=>'Hola '+o.client+', su orden '+o.code+' se encuentra en estado: '+o.status+'.'+o.track]];
function prepareWhatsApp(order){const dialog=smallDialog('Mensaje de WhatsApp · '+order.code),form=el('form',undefined,'whatsapp-form');dialog.classList.add('agenda-dialog');form.noValidate=true;const target=whatsappNumber(order.phone),money=cents=>new Intl.NumberFormat('es-EC',{style:'currency',currency:'USD'}).format(cents/100);
 const data={client:order.client||'cliente',code:order.code,device:[order.brand,order.model].filter(Boolean).join(' ')||'equipo',status:statusNames[order.status]||order.status,findings:(order.findings||'').trim(),total:order.budget?.total_cents?money(order.budget.total_cents):'',track:order.tracking?.url?' Puede consultar el avance aquí: '+order.tracking.url:''};
 const to=el('p','','agenda-hint');to.textContent=target.ok?'Para: '+order.client+' · +'+target.number:target.reason+' Corrígelo en la ficha del cliente para poder escribirle.';to.dataset.state=target.ok?'ok':'error';const pick=field(form,'Tipo de mensaje','template','',{select:true});whatsappTemplates.forEach(([name],index)=>pick.add(new Option(name,String(index))));const text=field(form,'Mensaje','message','',{textarea:true,maxLength:1500});text.rows=6;const fill=()=>{text.value=whatsappTemplates[+pick.value][1](data);};pick.onchange=fill;fill();
 const bar=el('div',undefined,'agenda-actions'),send=el('button','Abrir WhatsApp','primary');send.type='submit';send.disabled=!target.ok;bar.append(button('Cancelar',()=>dialog.close(),'secondary'));if(!target.ok&&order.client_id)bar.append(button('Abrir ficha del cliente',()=>{dialog.close();showClientDetail(order.client_id);},'secondary'));bar.append(send);form.prepend(to);form.append(el('p','El mensaje se abre en WhatsApp para que lo revises y lo envíes tú. El sistema no puede saber si el número tiene WhatsApp ni si el mensaje se envió.','agenda-hint'),bar);
 form.onsubmit=event=>{event.preventDefault();if(!text.value.trim()){text.focus();return;}if(openWhatsApp(order.phone,text.value.trim()))dialog.close();};dialog.append(form);text.focus();}

