function appendAccessEvidence(root,order){const section=el('section',undefined,'terms-evidence');section.append(el('h3','Autorización de acceso técnico'));const a=order.access_authorization;section.append(el('p',a?'Acceso técnico: '+(a.decision==='authorized'?'AUTORIZADO':'NO AUTORIZADO'):'No consta autorización'));if(a){section.append(el('p','Decisión: '+formatOrderDate(a.recorded_at)+' · Responsable: '+a.operator));section.append(el('p','Alcance: '+(Object.entries(accessScopeLabels).filter(([k])=>a.permissions[k]).map(([,v])=>v).join('; ')||'Sin acceso permitido')));if(a.decision==='authorized'&&a.permissions.files_decision==='denied')section.append(el('p','Archivos y respaldos: NO AUTORIZADO (rechazo expreso del cliente)'));if(a.justification)section.append(el('p',a.justification));}const d=order.destructive_authorization;section.append(el('p','Reinstalación / eliminación: '+(d?(d.decision==='authorized'?'Autorización adicional registrada':'NO AUTORIZADO'):'Sin autorización adicional')));if(d){const ops=Object.entries(accessRiskLabels).filter(([key])=>d.permissions?.[key]).map(([,text])=>text);if(ops.length)section.append(el('p','Operaciones autorizadas: '+ops.join('; ')));section.append(el('p',formatOrderDate(d.recorded_at)+' · '+d.operator+' · '+d.justification));}if(order.authorization_mail){const m=order.authorization_mail;section.append(el('p','Aviso al correo administrativo: '+({sent:'enviado',failed:'no se pudo enviar',not_configured:'no enviado (correo del sistema sin configurar)'}[m.result]||m.result)+' · '+formatOrderDate(m.created_at)+(m.result==='failed'&&m.detail?' · '+m.detail:''),'small'));}if(order.access_history?.length){const details=el('details');details.append(el('summary','Historial de decisiones ('+order.access_history.length+')'));for(const row of order.access_history)details.append(el('p',formatOrderDate(row.recorded_at)+' · '+(row.action==='technical'?'Acceso técnico':'Reinstalación / eliminación')+' · '+(row.decision==='authorized'?'Autorizado':'No autorizado')+' · '+row.operator));section.append(details);}root.append(section);}
