 const dialog=el('dialog',undefined,'workspace-editor');dialog.setAttribute('aria-label','Registrar decisión expresa del cliente');const form=el('form');form.noValidate=true;const header=el('header');header.append(el('h2','Autorización · '+order.code),closeIcon(()=>requestModalClose(dialog)));const body=el('div',undefined,'workspace-edit-fields');const access=accessFields('authorization');access.classList.add('full');body.append(access);let terms=null;
