 const status=el('p','','message');status.setAttribute('role','status');const footer=el('footer'),save=el('button','Guardar decisión','primary');save.type='submit';footer.append(button('Cancelar',()=>requestModalClose(dialog)),save);form.append(header,body,status,footer);dialog.append(form);document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.showModal();header.querySelector('h2').tabIndex=-1;header.querySelector('h2').focus();newRequestKey(form);
