 function live(delay=320){clear.hidden=!input.value;clearTimeout(timer);timer=setTimeout(()=>{const value=input.value.trim();if(value===(params.get('q')||''))return;refresh(withQuery(value));},delay);}
 input.addEventListener('input',()=>live());
